-- Phase 5 Part 5: offline and paper entries (idempotent sync) and supervisor review.
-- Generated by prisma migrate diff, followed by a hand-written section.

-- AlterTable
ALTER TABLE "visits" ADD COLUMN     "client_ref" UUID,
ADD COLUMN     "review_note" TEXT,
ADD COLUMN     "review_reason" TEXT,
ADD COLUMN     "reviewed_at" TIMESTAMPTZ(3),
ADD COLUMN     "reviewed_by_user_id" UUID;

-- CreateIndex
CREATE UNIQUE INDEX "visits_organisation_id_client_ref_key" ON "visits"("organisation_id", "client_ref");

-- AddForeignKey
ALTER TABLE "visits" ADD CONSTRAINT "visits_reviewed_by_user_id_fkey" FOREIGN KEY ("reviewed_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- =============================================================================================
-- Hand-written below this line: rules for offline and paper entries and their review.
-- See docs/architecture/DATA_MODEL.md section 5 and docs/operations/GATE_OFFLINE.md.
-- =============================================================================================

-- Entries recorded after the fact carry the device's reference (idempotent sync).
ALTER TABLE "visits" ADD CONSTRAINT "visits_client_ref_for_late_entries"
  CHECK ("source" = 'ONLINE' OR "client_ref" IS NOT NULL);

-- Only entries recorded after the fact can be flagged; live admissions were checked at the time.
ALTER TABLE "visits" ADD CONSTRAINT "visits_review_reason"
  CHECK ("review_reason" IS NULL
         OR ("source" <> 'ONLINE' AND "review_reason" ~ '^[A-Z_]{3,40}$'));
-- A review records who and when, follows a flag, and may carry a short note.
ALTER TABLE "visits" ADD CONSTRAINT "visits_review_consistent"
  CHECK (("reviewed_at" IS NULL) = ("reviewed_by_user_id" IS NULL)
         AND ("reviewed_at" IS NULL OR "review_reason" IS NOT NULL)
         AND ("review_note" IS NULL OR "reviewed_at" IS NOT NULL)
         AND ("review_note" IS NULL OR length(btrim("review_note")) BETWEEN 1 AND 500));

-- A visit is a record of what happened. Two things may be added later, each once: the departure,
-- and a supervisor's review of a flagged entry. Everything else never changes (replaces the
-- Part 3 version).
CREATE OR REPLACE FUNCTION app_visit_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."invitation_id", NEW."pass_id",
      NEW."walk_in_request_id", NEW."category", NEW."visitor_name", NEW."visitor_phone",
      NEW."vehicle_plate", NEW."decision", NEW."denial_reason", NEW."gate", NEW."arrived_at",
      NEW."recorded_by_user_id", NEW."source", NEW."client_ref", NEW."review_reason",
      NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."invitation_id", OLD."pass_id",
      OLD."walk_in_request_id", OLD."category", OLD."visitor_name", OLD."visitor_phone",
      OLD."vehicle_plate", OLD."decision", OLD."denial_reason", OLD."gate", OLD."arrived_at",
      OLD."recorded_by_user_id", OLD."source", OLD."client_ref", OLD."review_reason",
      OLD."created_at") THEN
    RAISE EXCEPTION 'visit % is a record and cannot be edited', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."departed_at" IS NOT NULL
     AND (NEW."departed_at", NEW."departure_recorded_by_user_id")
         IS DISTINCT FROM (OLD."departed_at", OLD."departure_recorded_by_user_id") THEN
    RAISE EXCEPTION 'the departure of visit % is already recorded', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."departed_at" IS NULL AND NEW."departed_at" IS NULL
     AND NEW."departure_recorded_by_user_id" IS NOT NULL THEN
    RAISE EXCEPTION 'visit % has no departure to attribute', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."reviewed_at" IS NOT NULL
     AND (NEW."reviewed_at", NEW."reviewed_by_user_id", NEW."review_note")
         IS DISTINCT FROM (OLD."reviewed_at", OLD."reviewed_by_user_id", OLD."review_note") THEN
    RAISE EXCEPTION 'visit % is already reviewed', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
